package engine_test

import (
	"testing"

	"github.com/acityonmars/martian-robots/internal/engine"
)

func Test_HasPosition_Includes_Grid_Edges_And_Excludes_Outside(t *testing.T) {
	world := newTestWorld(engine.Position{X: 5, Y: 3})

	cases := []struct {
		name string
		pos  engine.Position
		want bool
	}{
		{"lower-left corner", engine.Position{X: 0, Y: 0}, true},
		{"upper-right corner", engine.Position{X: 5, Y: 3}, true},
		{"left of grid", engine.Position{X: -1, Y: 0}, false},
		{"below grid", engine.Position{X: 0, Y: -1}, false},
		{"right of grid", engine.Position{X: 6, Y: 3}, false},
		{"above grid", engine.Position{X: 5, Y: 4}, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := world.HasPosition(tc.pos); got != tc.want {
				t.Errorf("HasPosition(%v) = %v, want %v", tc.pos, got, tc.want)
			}
		})
	}
}

func Test_MoveTo_Handles_On_Grid_Lost_And_Scented_Moves(t *testing.T) {
	t.Run("on grid: robot moves", func(t *testing.T) {
		world := newTestWorld(engine.Position{X: 5, Y: 3})
		robot := &engine.Robot{Pos: engine.Position{X: 1, Y: 1}, Ori: engine.North}

		world.MoveTo(robot, engine.Position{X: 1, Y: 2})

		if got, want := robot.String(), "1 2 N"; got != want {
			t.Errorf("robot = %q, want %q", got, want)
		}
	})

	t.Run("off grid without scent: robot is lost at last cell and leaves scent", func(t *testing.T) {
		world := newTestWorld(engine.Position{X: 5, Y: 3})
		edge := engine.Position{X: 5, Y: 3}
		robot := &engine.Robot{Pos: edge, Ori: engine.North}

		world.MoveTo(robot, engine.Position{X: 5, Y: 4})

		if got, want := robot.String(), "5 3 N LOST"; got != want {
			t.Errorf("robot = %q, want %q", got, want)
		}
		if !world.HasScent(edge) {
			t.Errorf("no scent at %v, want scent at last on-grid cell", edge)
		}
	})

	t.Run("off grid from scented cell: move is ignored, even in another direction", func(t *testing.T) {
		world := newTestWorld(engine.Position{X: 5, Y: 3})
		edge := engine.Position{X: 5, Y: 3}
		first := &engine.Robot{Pos: edge, Ori: engine.North}
		world.MoveTo(first, engine.Position{X: 5, Y: 4}) // lost going north: leaves scent

		// Scent is keyed by position only, so leaving east from the same cell is also blocked.
		second := &engine.Robot{Pos: edge, Ori: engine.East}
		world.MoveTo(second, engine.Position{X: 6, Y: 3})

		if got, want := second.String(), "5 3 E"; got != want {
			t.Errorf("robot = %q, want %q (not lost)", got, want)
		}
	})
}
